import { ParentSize } from '@visx/responsive';
import { Line as ZeroLine } from '@visx/shape';
import { isNil } from 'lodash-es';
import React, { PropsWithChildren } from 'react';

import { SparklineDisplay } from './SparklineDisplay.js';
import { useCurrentTheme } from '../../../core/hooks/useCurrentTheme.js';
import { OldTimeBottomAxis } from '../../core/components/axes/components/OldTimeBottomAxis.js';
import { Canvas } from '../../core/components/canvas/Canvas.js';
import { CanvasContext } from '../../core/components/canvas/CanvasContext.js';
import { createCanvasGradient } from '../../core/components/canvas/functions/create-canvas-gradient.js';
import { CanvasShape } from '../../core/components/canvas/types/canvas-shape.js';
import { ChartStateHandler } from '../../core/components/chart-states/ChartStateHandler.js';
import { getChartStatesTemplates } from '../../core/components/chart-states/functions/get-chart-states-template.js';
import {
  DEFAULT_STROKE_COLOR,
  DEFAULT_STROKE_WIDTH,
} from '../../core/components/grid/GridLine.js';
import { ThresholdIndicator } from '../../core/components/threshold-bar/indicators/ThresholdIndicator.js';
import { getValidColor } from '../../core/functions/getValidColor.js';
import { Timeseries } from '../../core/types/timeseries.js';
import { defaultYAxisConfig } from '../constants.js';
import { getSparklineXScale } from '../functions/get-sparkline-x-scale.js';
import { getSparklineYScale } from '../functions/get-sparkline-y-scale.js';
import { sanitizeSparklineData } from '../functions/sanitize-sparkline-data.js';
import { calculateStrokeWidth } from '../functions/stroke-width.js';
import { mapToThresholdsIndicators } from '../functions/threshold-indicators.js';
import { SparklineThresholdProps } from '../slots/Threshold.js';
import { SparklineYAxisProps } from '../slots/YAxis.js';
import { SparklineProps } from '../Sparkline.js';

export interface SparklineRendererProps extends SparklineProps {
  thresholds?: SparklineThresholdProps[];
  yAxis?: SparklineYAxisProps;
}

const AXIS_HEIGHT = 25;

/**
 * SparklineRenderer component
 */
export const SparklineRenderer = (
  props: PropsWithChildren<SparklineRendererProps>,
) => {
  const {
    data,
    color,
    variant = 'line',
    showTicks = false,
    thresholds = [],
    loading = false,
    yAxis = defaultYAxisConfig,
    gapPolicy = 'connect',
    children,
    curve,
  } = props;
  const series: Timeseries = Array.isArray(data) ? data[0] : data;
  const theme = useCurrentTheme();

  const { emptyState, errorState } = getChartStatesTemplates(children);

  const isEmpty = isNil(series);

  return (
    <ChartStateHandler
      data-testid="sparkline-state-handler"
      empty={isEmpty}
      height={'100%'}
      emptyState={emptyState}
      errorState={errorState}
      isLoading={loading}
    >
      <ParentSize
        parentSizeStyles={{
          height: '100%',
          width: '100%',
          transform: 'translate(0,0)',
        }}
      >
        {(parent) => {
          const shouldShowTicks = showTicks && parent.height >= 40;

          const ticksOffset = shouldShowTicks ? AXIS_HEIGHT : 0;

          const height = Math.max(0, parent.height - ticksOffset);
          const { width } = parent;

          const strokeWidth = calculateStrokeWidth(width, height);

          const { sanitizedSeries, sanitizedValues } = isEmpty
            ? series
            : sanitizeSparklineData(series, gapPolicy);

          const xScale = getSparklineXScale(
            sanitizedSeries,
            width,
            strokeWidth / 2,
          );

          const yScale = getSparklineYScale(sanitizedValues, height, yAxis);

          const thresholdIndicators = mapToThresholdsIndicators(
            thresholds,
            width,
            height,
            xScale,
            yScale,
          );

          const validatedColor = getValidColor(color);

          const [min, max] = yScale.domain();
          const displayZeroLine = min <= 0 && max >= 0;
          const zeroLineYPos = yScale(0) ?? -1;

          return (
            <>
              <svg
                width={width}
                height={parent.height}
                data-testid="sparkline"
                style={{ position: 'absolute' }}
              >
                {displayZeroLine && (
                  <ZeroLine
                    from={{ x: 0, y: zeroLineYPos }}
                    to={{ x: width, y: zeroLineYPos }}
                    stroke={DEFAULT_STROKE_COLOR}
                    strokeWidth={DEFAULT_STROKE_WIDTH}
                    data-testid="sparkline-zero-baseline"
                  />
                )}
                {thresholdIndicators.length &&
                  thresholdIndicators.map(
                    ({ id, indicatorData, color, strokeOnly }) => (
                      <ThresholdIndicator
                        key={`threshold-indicator-${id}`}
                        data={indicatorData}
                        color={color}
                        strokeOnly={strokeOnly}
                        isActive={false}
                      />
                    ),
                  )}
              </svg>
              <div style={{ position: 'absolute' }}>
                <CanvasContext.Provider
                  value={{
                    shapeRefs: new Map<
                      string,
                      React.MutableRefObject<CanvasShape>
                    >(),
                  }}
                >
                  <Canvas width={width} height={height}>
                    <SparklineDisplay
                      data={sanitizedSeries.datapoints}
                      width={width}
                      height={height}
                      xScale={xScale}
                      yScale={yScale}
                      strokeColor={validatedColor}
                      fillColor={createCanvasGradient({
                        height,
                        color: validatedColor,
                        domain: yScale.domain(),
                        theme,
                      })}
                      variant={variant}
                      strokeWidth={strokeWidth}
                      curve={curve}
                    />
                  </Canvas>
                </CanvasContext.Provider>
                {shouldShowTicks && (
                  <OldTimeBottomAxis
                    scale={xScale}
                    containerHeight={AXIS_HEIGHT}
                    containerWidth={width}
                  />
                )}
              </div>
            </>
          );
        }}
      </ParentSize>
    </ChartStateHandler>
  );
};

SparklineRenderer['displayName'] = 'SparklineRenderer';
